-- U1 精读《Paper flowers in young hands》148 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U1', 'Paper flowers in young hands', 'Yang Xin is fourteen. Every Saturday she goes to her grandma''s small shop to learn paper cutting. Grandma has cut paper flowers for forty years. "If you want to learn this art, be patient," she often says. At first Yang Xin was not interested, because her friends thought paper cutting was old-fashioned. She wanted to spend her free time on videos and games. That winter, something changed. Her class needed something special for the school show. Since no one else had an idea, Yang Xin brought her paper flowers. Her classmates were amazed. "They look alive!" one boy said. Now Yang Xin runs a small club at school. If a new member feels lost, she sits down and shows the first cut again. "If you keep on, your hands will remember," she tells them. She believes the art will not disappear, because young hands are holding it now.', '青少年与传统技艺(条件·原因状语从句)', 148, 0, '[{"q": "Why was Yang Xin not interested in paper cutting at first?", "type": "choice", "answer": "B", "options": ["Because her grandma did not teach her.", "Because her friends thought it was old-fashioned.", "Because she had no free time at all.", "Because the shop was too far from her home."], "explanation": "''At first Yang Xin was not interested, because her friends thought paper cutting was old-fashioned.''"}, {"q": "What made Yang Xin bring her paper flowers to the school show?", "type": "choice", "answer": "C", "options": ["Her grandma asked her to do so.", "Her teacher gave her a task.", "Nobody else had an idea for the show.", "She wanted to win a prize."], "explanation": "''Since no one else had an idea, Yang Xin brought her paper flowers.''"}, {"q": "What is the passage mainly about?", "type": "choice", "answer": "A", "options": ["How a girl came to love a traditional art and passed it on.", "How to cut paper flowers step by step.", "Why school shows are important for students.", "How a grandma opened a small shop."], "explanation": "全文按「起初不感兴趣 → 学校演出的转折 → 现在带社团」的顺序,讲一个女孩爱上并传承剪纸。"}, {"q": "What can we learn about Yang Xin from the last paragraph?", "type": "choice", "answer": "D", "options": ["She will close the club soon.", "She thinks the art is already gone.", "She wants to sell paper flowers.", "She is hopeful about the future of the art."], "explanation": "''She believes the art will not disappear, because young hands are holding it now.'' 说明她对这门艺术的未来抱有信心。"}, {"q": "What does the underlined phrase \"keep on\" mean in the passage?", "type": "choice", "answer": "B", "options": ["stop for a rest", "go on doing something", "put something away", "ask for help"], "explanation": "''If you keep on, your hands will remember'' —— 与前句「新成员感到迷茫时再示范一次」呼应,意为坚持做下去。"}]'::jsonb, '[{"word": "paper cutting", "cn": "剪纸(中国传统手工艺)"}, {"word": "patient", "cn": "有耐心的"}, {"word": "old-fashioned", "cn": "老式的,过时的"}, {"word": "keep on", "cn": "坚持下去"}, {"word": "disappear", "cn": "消失"}]'::jsonb);
-- U1 泛读《The club that almost closed》140 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U1', 'The club that almost closed', 'Last term our school drama club had only four members. If nobody joined, the club would close. We felt helpless, because most students thought drama was only for people with a loud voice. Our teacher had one idea. "If you want new members, show them what you do," she said. So we put on a ten-minute play at lunchtime, right in the middle of the dining hall. Some students stopped eating. Some took out their phones. By Friday, eleven people came to ask about us. Now the club is full. We still lose our lines sometimes, and we still laugh at ourselves. But if a shy student comes to the door, we always say the same thing: come in and try one line. Because a club does not grow when you talk about it. It grows when people see it.', '青少年与传统技艺(条件·原因状语从句)', 140, 1, '[{"q": "Why did the drama club nearly close last term?", "type": "choice", "answer": "C", "options": ["Because the teacher left the school.", "Because the members were too busy.", "Because it had too few members.", "Because the dining hall was closed."], "explanation": "''Last term our school drama club had only four members. If nobody joined, the club would close.''"}, {"q": "What did the club do to get new members?", "type": "choice", "answer": "A", "options": ["They performed a short play in the dining hall.", "They put up posters in every classroom.", "They asked the teacher to help them.", "They made a video for the school website."], "explanation": "''So we put on a ten-minute play at lunchtime, right in the middle of the dining hall.''"}, {"q": "What does the writer want to tell us?", "type": "choice", "answer": "D", "options": ["Drama is only for students with a loud voice.", "A club needs a big room to grow.", "Shy students should not join a drama club.", "Showing what you do works better than talking about it."], "explanation": "''a club does not grow when you talk about it. It grows when people see it.''"}]'::jsonb, '[{"word": "drama", "cn": "戏剧;戏剧社"}, {"word": "helpless", "cn": "无助的(help + -less)"}, {"word": "shy", "cn": "害羞的"}]'::jsonb);
-- U1 泛读《My grandpa's radio》140 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U1', 'My grandpa''s radio', 'My grandpa keeps an old radio on the kitchen table. It is heavy and brown, and one button is missing. Every morning he turns it on while he makes tea. Last year I bought him a small speaker. "If you use this, you can hear a hundred stations," I said. He thanked me and put it on the shelf. The old radio stayed on the table. I did not understand, because the new one was clearly better. Then one evening he told me about my grandma. They listened to that radio together for thirty years. Since she passed, the morning music has been the one thing that still sounds like her. I stopped asking him to change. Now, when I visit, I make the tea and he turns on the radio. Some old things are not about sound at all.', '青少年与传统技艺(条件·原因状语从句)', 140, 1, '[{"q": "Why did the writer buy a speaker for grandpa?", "type": "choice", "answer": "B", "options": ["Because the old radio was broken.", "Because the writer thought it was better.", "Because grandpa asked for one.", "Because grandma liked new music."], "explanation": "''If you use this, you can hear a hundred stations,'' 与 ''because the new one was clearly better'' 说明写作者认为新音箱更好。"}, {"q": "Why does grandpa keep using the old radio?", "type": "choice", "answer": "D", "options": ["Because it is easy to move.", "Because the speaker does not work.", "Because it has more stations.", "Because it reminds him of grandma."], "explanation": "''Since she passed, the morning music has been the one thing that still sounds like her.''"}, {"q": "How did the writer feel at the end?", "type": "choice", "answer": "A", "options": ["He came to understand grandpa.", "He was angry with grandpa.", "He wanted to buy another speaker.", "He was sorry he had visited."], "explanation": "''I stopped asking him to change. Now, when I visit, I make the tea and he turns on the radio.'' 说明他理解了爷爷。"}]'::jsonb, '[{"word": "speaker", "cn": "音箱,扬声器"}, {"word": "station", "cn": "电台(此处不是「车站」)"}, {"word": "shelf", "cn": "架子,搁板"}]'::jsonb);
-- U1 泛读《Two hours a week》141 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U1', 'Two hours a week', 'Li Nan is fifteen. Every Sunday afternoon he spends two hours at the city library, but he does not go there to read. He goes to help small children choose books. He started last spring. Since his own reading was slow when he was seven, he knows how it feels to stand in front of a tall shelf and see nothing you can finish. "If a book is too hard, put it back," he tells them. "There is no prize for a thick book." Some parents were not happy at first, because they wanted their children to read long stories. Li Nan did not argue. He just kept coming. By June, twelve children were waiting for him at the door every Sunday. "If you enjoy the first ten pages, you will finish the book," he says. "That is the whole secret."', '青少年与传统技艺(条件·原因状语从句)', 141, 1, '[{"q": "What does Li Nan do at the library?", "type": "choice", "answer": "C", "options": ["He reads long stories.", "He works at the front desk.", "He helps young children choose books.", "He teaches parents how to read."], "explanation": "''He goes to help small children choose books.''"}, {"q": "Why can Li Nan understand the children so well?", "type": "choice", "answer": "B", "options": ["Because he works with teachers.", "Because his own reading was slow when he was young.", "Because he reads a book every day.", "Because his parents are librarians."], "explanation": "''Since his own reading was slow when he was seven, he knows how it feels…''"}, {"q": "What is Li Nan''s advice to the children?", "type": "choice", "answer": "A", "options": ["Start with a book you enjoy.", "Always choose the thickest book.", "Read for two hours every Sunday.", "Ask your parents to choose for you."], "explanation": "''If a book is too hard, put it back.'' 与 ''If you enjoy the first ten pages, you will finish the book.''"}]'::jsonb, '[{"word": "shelf", "cn": "书架"}, {"word": "argue", "cn": "争辩,争论"}, {"word": "secret", "cn": "秘诀(此处不是「秘密」)"}]'::jsonb);
-- U1 泛读《The wall behind the school》135 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U1', 'The wall behind the school', 'The grey wall behind our school was ugly for years. Old posters hung on it, and nobody looked at them twice. In March, our art teacher asked a question: "If we cannot move the wall, can we change it?" Twenty of us said yes. We drew a river, a bridge and a line of young trees. Work was slow, because we could only paint after class. Some days it rained and we lost a whole afternoon. One boy wanted to stop. "Nobody will notice," he said. He was wrong. Since the wall was finished, three other classes have asked to paint the corner near the gate. Now people take photos there. If you walk past our school on a Friday, you will see a line of students with brushes, and a wall that keeps growing.', '青少年与传统技艺(条件·原因状语从句)', 135, 1, '[{"q": "What was the wall like before March?", "type": "choice", "answer": "B", "options": ["It was covered with paintings.", "It was grey with old posters on it.", "It was hidden behind young trees.", "It was used as a photo corner."], "explanation": "''The grey wall behind our school was ugly for years. Old posters hung on it…''"}, {"q": "Why did the work take a long time?", "type": "choice", "answer": "D", "options": ["Because the wall was very high.", "Because only two students helped.", "Because the teacher was often away.", "Because they could paint only after class and rain stopped them."], "explanation": "''Work was slow, because we could only paint after class. Some days it rained and we lost a whole afternoon.''"}, {"q": "What happened after the wall was finished?", "type": "choice", "answer": "C", "options": ["The school painted it grey again.", "The paintings were washed off by the rain.", "Other classes asked to paint another corner.", "The teacher asked for new posters."], "explanation": "''Since the wall was finished, three other classes have asked to paint the corner near the gate.''"}]'::jsonb, '[{"word": "poster", "cn": "海报"}, {"word": "brush", "cn": "刷子;画笔"}, {"word": "ugly", "cn": "难看的,丑的"}]'::jsonb);
-- U2 精读《Three glass jars》160 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U2', 'Three glass jars', 'Chen Yu wanted a real basketball. It cost 180 yuan, and his pocket money was 20 yuan a week. At first he kept everything in one pocket. When Friday came, the money was always gone, and he never knew where it went. One evening his mum put three old glass jars on the table. "Try these," she said. "One jar for the ball, one for small things, one for gifts." While he was washing the jars, Chen Yu thought the plan was silly. He tried it anyway. He did not touch the ball jar until it was full. Some weeks he put in only five yuan. Once he took two yuan back, and he felt bad for days. After that he wrote the date on the jar before he spent anything. Since that autumn, Chen Yu has kept the three jars on his desk. He bought the basketball in March. Now it sits where he can see it every morning.', '零花钱与理财(时间·地点状语从句)', 160, 0, '[{"q": "What was Chen Yu''s problem at first?", "type": "choice", "answer": "C", "options": ["His pocket money was cut by his parents.", "He lost his basketball at school.", "His money was gone by Friday and he did not know why.", "His mum would not buy him three jars."], "explanation": "''When Friday came, the money was always gone, and he never knew where it went.''"}, {"q": "What did Chen Yu think of the jars at the beginning?", "type": "choice", "answer": "A", "options": ["He thought the plan was silly.", "He thought the jars were too small.", "He was very excited about them.", "He asked for three more jars."], "explanation": "''While he was washing the jars, Chen Yu thought the plan was silly.''"}, {"q": "When did Chen Yu take money out of the ball jar?", "type": "choice", "answer": "D", "options": ["Every Sunday.", "When the jar was full.", "Never.", "Once, and it made him feel bad."], "explanation": "''Once he took two yuan back, and he felt bad for days.'' 说明他只拿过一次,而且很不好受。"}, {"q": "What is the passage mainly about?", "type": "choice", "answer": "B", "options": ["How to choose a good basketball.", "How a boy learnt to manage his pocket money.", "Why glass jars are better than moneyboxes.", "How a mother saved for her son."], "explanation": "全文按「钱总是不见 → 用三个罐子 → 坚持到买下篮球」的顺序,讲一个男孩学会管理零花钱。"}, {"q": "What does the underlined word \"went\" mean in \"he never knew where it went\"?", "type": "choice", "answer": "B", "options": ["walked away", "was spent", "was saved", "got lost in the street"], "explanation": "''When Friday came, the money was always gone'' —— 前句说钱到周五总是没了,故 went 指钱被花掉了。"}]'::jsonb, '[{"word": "pocket money", "cn": "零花钱"}, {"word": "jar", "cn": "罐子"}, {"word": "silly", "cn": "傻的,愚蠢的"}, {"word": "date", "cn": "日期"}, {"word": "touch", "cn": "动用(此处指从罐里取钱)"}]'::jsonb);
-- U2 泛读《The Saturday market》138 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U2', 'The Saturday market', 'Every spring our school holds a small market on the playground. Students bring old books, toys and clothes. Before the market opens, each seller writes a price on a paper card. Last year I sold twelve books. My first price was ten yuan for each one. Nobody stopped. While I was watching the next table, I saw something useful: the girl beside me put three books together for fifteen yuan. As soon as I changed my cards, buyers came. I did not count the money until the market closed. I had eighty-six yuan. It was not a big number, but I learnt something better. A price is not about my wish. It is about the buyer. Since that Saturday, I have kept the paper cards in my desk. When I plan anything now, I start with the buyer.', '零花钱与理财(时间·地点状语从句)', 138, 1, '[{"q": "Why did nobody stop at the writer''s table at first?", "type": "choice", "answer": "B", "options": ["Because the books were too old.", "Because the price of each book was too high.", "Because the table was in a bad place.", "Because the market opened too late."], "explanation": "''My first price was ten yuan for each one. Nobody stopped.'' 与后文改价后买家就来了,说明是价格问题。"}, {"q": "What did the writer learn from the girl beside him?", "type": "choice", "answer": "C", "options": ["To sell books at a higher price.", "To bring more books next time.", "To sell three books together for one price.", "To count the money before the market closed."], "explanation": "''the girl beside me put three books together for fifteen yuan. As soon as I changed my cards, buyers came.''"}, {"q": "What does the writer think about a price now?", "type": "choice", "answer": "A", "options": ["It should depend on the buyer.", "It should be as high as possible.", "It should be written on a paper card.", "It should never be changed."], "explanation": "''A price is not about my wish. It is about the buyer.''"}]'::jsonb, '[{"word": "seller", "cn": "卖家(sell + -er)"}, {"word": "buyer", "cn": "买家(buy + -er)"}, {"word": "paper card", "cn": "纸卡片(此处指标价牌)"}]'::jsonb);
-- U2 泛读《A gift for my sister》145 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U2', 'A gift for my sister', 'My sister''s birthday is in July. Last year I wanted to buy her a real drawing book, but it cost 65 yuan and I had nothing in my pocket. In March I started to walk to school. The bus is two yuan each way, so I saved four yuan a day. After I got home, I put the coins in a paper envelope under my books. While I was saving, the price went up to 72 yuan. That was bad news. I did not tell anyone. I just kept walking. By the end of June the envelope was heavy. When the shop assistant counted my coins, she smiled and asked if I was buying a gift. My sister still uses that drawing book. She does not know about the envelope, and I will not tell her. Some gifts are better when the story stays quiet.', '零花钱与理财(时间·地点状语从句)', 145, 1, '[{"q": "How did the writer save money?", "type": "choice", "answer": "D", "options": ["By selling his old books.", "By asking his parents for more pocket money.", "By working in a shop after school.", "By walking to school instead of taking the bus."], "explanation": "''In March I started to walk to school. The bus is two yuan each way, so I saved four yuan a day.''"}, {"q": "What happened while the writer was saving?", "type": "choice", "answer": "A", "options": ["The drawing book became more expensive.", "His sister found the envelope.", "He lost some of his coins.", "The shop closed for a month."], "explanation": "''While I was saving, the price went up to 72 yuan.''"}, {"q": "Why will the writer not tell his sister about the envelope?", "type": "choice", "answer": "C", "options": ["Because he is afraid of his parents.", "Because he wants her to pay him back.", "Because he thinks a quiet story makes a better gift.", "Because he has forgotten the price."], "explanation": "''Some gifts are better when the story stays quiet.''"}]'::jsonb, '[{"word": "envelope", "cn": "信封"}, {"word": "shop assistant", "cn": "店员"}, {"word": "coin", "cn": "硬币"}]'::jsonb);
-- U2 泛读《The classroom bank》135 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U2', 'The classroom bank', 'Our class has a small bank. It is only a wooden box on the back shelf, but it works. Here is the idea. When you forget a pen or a ruler, you borrow one from the box. Before you take it, you write your name and the date on the list. After you return it, you cross your name out. Wang Lei looks after the box. He does not open it until the first lesson begins, and he closes it as soon as the last bell rings. At first some students laughed. They thought a real bank should hold money. But since we started the box in September, nobody in our class has bought a new ruler in a hurry. Wherever you sit, the box is only ten steps away. That is the whole point.', '零花钱与理财(时间·地点状语从句)', 135, 1, '[{"q": "What is the \"classroom bank\"?", "type": "choice", "answer": "B", "options": ["A safe box for students'' pocket money.", "A wooden box for borrowing pens and rulers.", "A shop near the school gate.", "A list of students'' names on the wall."], "explanation": "''Our class has a small bank. It is only a wooden box on the back shelf'' 与 ''you borrow one from the box''。"}, {"q": "When does Wang Lei close the box?", "type": "choice", "answer": "D", "options": ["Before the first lesson begins.", "While the students are writing.", "After the students laugh.", "As soon as the last bell rings."], "explanation": "''he closes it as soon as the last bell rings.''"}, {"q": "What has changed since September?", "type": "choice", "answer": "A", "options": ["Students no longer buy new rulers in a hurry.", "The box has been moved to the front shelf.", "Wang Lei has stopped looking after the box.", "The class has bought a real bank box."], "explanation": "''since we started the box in September, nobody in our class has bought a new ruler in a hurry.''"}]'::jsonb, '[{"word": "wooden", "cn": "木制的(wood + -en)"}, {"word": "borrow", "cn": "借入(与 lend「借出」相对)"}, {"word": "wherever", "cn": "无论在哪里"}]'::jsonb);
-- U2 泛读《Grandma's little book》129 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U2', 'Grandma''s little book', 'My grandma has kept a small account book for thirty years. It is grey and soft at the corners. Every evening, after she washes the bowls, she sits down and writes two lines: one line for money in, one line for money out. When I was little, I thought it was boring. Last winter my mother wanted to change the old washing machine. She and my father talked about the price for a week. Then grandma opened her book. While they were still talking, she showed them a page from last March. The same machine was 300 yuan cheaper before the New Year. They waited. In January they bought it at the lower price. Now I understand. Grandma''s little book is not really about money. It is about time.', '零花钱与理财(时间·地点状语从句)', 129, 1, '[{"q": "What does grandma write in her book every evening?", "type": "choice", "answer": "C", "options": ["The names of her family.", "The weather of the day.", "The money coming in and going out.", "The price of the old washing machine."], "explanation": "''she sits down and writes two lines: one line for money in, one line for money out.''"}, {"q": "How did grandma help her family?", "type": "choice", "answer": "A", "options": ["She showed them the price of the machine last March.", "She lent them 300 yuan.", "She bought the machine herself.", "She asked the shop for a lower price."], "explanation": "''she showed them a page from last March. The same machine was 300 yuan cheaper before the New Year.''"}, {"q": "What does the writer mean by \"It is about time\"?", "type": "choice", "answer": "B", "options": ["Grandma is getting old.", "The book shows the best time to buy.", "The book takes a lot of time to write.", "The family is always late."], "explanation": "全文用「等到一月以更低价格买下」说明这本账本记的是时间带来的价格变化。"}]'::jsonb, '[{"word": "account", "cn": "账目;账户"}, {"word": "washing machine", "cn": "洗衣机"}, {"word": "lower", "cn": "更低的(low 的比较级)"}]'::jsonb);
-- U3 精读《A brush and a broken bowl》166 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U3', 'A brush and a broken bowl', 'Last summer our class visited a small museum in our town. An archaeologist there, Mr Zhou, was cleaning broken pieces of an old pot at a long table. He gave each of us a soft brush. "Work slowly so that you do not lose the smallest piece," he said. The pieces looked so plain that some of us were disappointed. We wanted gold. Mr Zhou smiled. "A whole pot shows you the shape. A broken pot brings out the story." It was such a hot afternoon that we drank all our water before three o''clock. Nobody left. By five we put together half of a bowl. Mr Zhou keeps a photo of that bowl on his wall. He shows it to visitors so that they can see how slow work looks. He takes more pride in it than in anything else in the room. Now, when I hear the word "history", I think of a table, a brush and a small grey piece in my hand.', '文物修复与历史(目的·结果状语从句)', 166, 0, '[{"q": "What was Mr Zhou doing when the class arrived?", "type": "choice", "answer": "C", "options": ["He was giving a speech to visitors.", "He was taking photos of a gold mask.", "He was cleaning broken pieces of an old pot.", "He was building a long table."], "explanation": "''An archaeologist there, Mr Zhou, was cleaning broken pieces of an old pot at a long table.''"}, {"q": "Why did Mr Zhou ask the students to work slowly?", "type": "choice", "answer": "A", "options": ["So that they would not lose the smallest piece.", "So that they could finish before three o''clock.", "Because the museum would close early.", "Because the brushes were too soft."], "explanation": "''Work slowly so that you do not lose the smallest piece.''"}, {"q": "How did some students feel at first?", "type": "choice", "answer": "D", "options": ["Afraid.", "Angry.", "Proud.", "Disappointed."], "explanation": "''The pieces looked so plain that some of us were disappointed. We wanted gold.''"}, {"q": "Why does Mr Zhou keep the photo of the bowl on his wall?", "type": "choice", "answer": "B", "options": ["Because the bowl is worth a lot of money.", "Because it shows visitors what slow work looks like.", "Because his class took the photo for him.", "Because the museum asked him to put it there."], "explanation": "''He shows it to visitors so that they can see how slow work looks.''"}, {"q": "What does \"brings out\" mean in \"A broken pot brings out the story\"?", "type": "choice", "answer": "B", "options": ["carries away", "makes something clear", "puts something back", "cleans the surface"], "explanation": "与前句 ''A whole pot shows you the shape'' 对照,brings out 指让故事显现出来。"}]'::jsonb, '[{"word": "archaeologist", "cn": "考古学家"}, {"word": "pot", "cn": "罐,陶罐"}, {"word": "plain", "cn": "朴素的,不起眼的"}, {"word": "disappointed", "cn": "失望的"}, {"word": "bring out", "cn": "使显现,让……显露出来"}]'::jsonb);
-- U3 泛读《The box under the bed》139 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U3', 'The box under the bed', 'My grandma keeps a small wooden box under her bed. Inside there is a collection of buttons — glass ones, wooden ones, one made of silk thread. Last winter I asked her to throw the box away. Our new flat was small. "These are not valuable," I said. She opened the box so that I could look more closely. Each button came from a coat, and each coat came from a year. The white one was from her wedding coat. The small brown one was from my father''s first school jacket. "A thing is not valuable because of its price," she said. Now the box sits on our new shelf. My little cousin likes to count the buttons. She is so careful that grandma lets her hold the white one. Some collections are not about the things at all.', '文物修复与历史(目的·结果状语从句)', 139, 1, '[{"q": "Why did the writer want to throw the box away?", "type": "choice", "answer": "B", "options": ["Because the buttons were broken.", "Because the new flat was small and he thought the buttons were not valuable.", "Because grandma asked him to do it.", "Because his cousin wanted a new box."], "explanation": "''Last winter I asked her to throw the box away. Our new flat was small. \"These are not valuable,\" I said.''"}, {"q": "Why did grandma open the box?", "type": "choice", "answer": "D", "options": ["To find a white button.", "To show her wedding coat.", "To count the buttons with her grandson.", "So that he could look at the buttons more closely."], "explanation": "''She opened the box so that I could look more closely.''"}, {"q": "What does the last sentence mean?", "type": "choice", "answer": "A", "options": ["A collection can be about memories, not things.", "Collections should be kept under a bed.", "Old buttons are worth a lot of money.", "Children should not touch old things."], "explanation": "''Some collections are not about the things at all.'' 与 ''\"A thing is not valuable because of its price\"'' 呼应,指收藏承载的是记忆。"}]'::jsonb, '[{"word": "collection", "cn": "收藏品"}, {"word": "silk", "cn": "丝绸"}, {"word": "thread", "cn": "线"}, {"word": "wedding", "cn": "婚礼"}]'::jsonb);
-- U3 泛读《The pattern on the scarf》123 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U3', 'The pattern on the scarf', 'Our art teacher brought an old scarf to class. The design on it was simple: three lines and a small bird. "This came from my hometown," she said. "Nobody uses it now." We looked at it for a long time. Then Xiao Man asked a question. "Can we put it on our class T-shirt?" The teacher was so pleased that she agreed at once. We worked for two weeks. We made the bird a little bigger so that people could see it from far away. On sports day, forty students wore the same bird. Other classes asked where we got the design. It is such a small pattern that nobody looked at it for years. Now it runs across a playground every spring.', '文物修复与历史(目的·结果状语从句)', 123, 1, '[{"q": "What was on the old scarf?", "type": "choice", "answer": "C", "options": ["Forty small birds.", "A picture of the teacher''s hometown.", "Three lines and a small bird.", "The name of the class."], "explanation": "''The design on it was simple: three lines and a small bird.''"}, {"q": "Why did the students make the bird bigger?", "type": "choice", "answer": "A", "options": ["So that people could see it from far away.", "Because the teacher asked them to.", "Because the T-shirt was too large.", "So that it could cover the three lines."], "explanation": "''We made the bird a little bigger so that people could see it from far away.''"}, {"q": "What happened to the old design in the end?", "type": "choice", "answer": "D", "options": ["It was put back in the teacher''s box.", "It was sold to another class.", "It was changed into three lines.", "It came back to life on the students'' T-shirts."], "explanation": "''On sports day, forty students wore the same bird.'' 与 ''Now it runs across a playground every spring.''"}]'::jsonb, '[{"word": "pattern", "cn": "图案,花样"}, {"word": "hometown", "cn": "家乡"}]'::jsonb);
-- U3 泛读《The tree at the corner》126 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U3', 'The tree at the corner', 'There is an old tree at the corner of our street. Nobody knows its age. Last year the road was made wider. Workers came with a machine, and the tree was in the way. That evening about thirty neighbours stood around it. Old Mr Lin brought a photo from many years ago. In the photo, a young man stood under the same tree with a bicycle. "That is my father," he said. The workers waited. The next week the plan changed, and the road turned a little so that the tree could stay. Now there is a small wooden sign beside it. Children read it on their way to school. The tree gives us shade in summer. It also gives us a place to stand together.', '文物修复与历史(目的·结果状语从句)', 126, 1, '[{"q": "Why was the tree in danger last year?", "type": "choice", "answer": "B", "options": ["Because it was too old to stand.", "Because the road was being made wider.", "Because children climbed it every day.", "Because Mr Lin wanted to move it."], "explanation": "''Last year the road was made wider. Workers came with a machine, and the tree was in the way.''"}, {"q": "What did Mr Lin bring that evening?", "type": "choice", "answer": "C", "options": ["A wooden sign.", "An old bicycle.", "An old photo of his father.", "A letter from the workers."], "explanation": "''Old Mr Lin brought a photo from many years ago. In the photo, a young man stood under the same tree with a bicycle. \"That is my father,\" he said.''"}, {"q": "How was the problem solved?", "type": "choice", "answer": "A", "options": ["The road was changed so that the tree could stay.", "The tree was moved to another street.", "The neighbours bought the land.", "The workers cut down half of the tree."], "explanation": "''The next week the plan changed, and the road turned a little so that the tree could stay.''"}]'::jsonb, '[{"word": "neighbour", "cn": "邻居"}, {"word": "sign", "cn": "牌子,标牌"}, {"word": "shade", "cn": "树荫,阴凉处"}]'::jsonb);
-- U3 泛读《Silk under glass》128 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U3', 'Silk under glass', 'Every Saturday morning I work at our town museum. My job is easy: I stand near the silk room and answer questions. The room is dark. Visitors often ask why. "Light is not kind to silk," I tell them. "We keep the room dark so that the colours can last." Some people are surprised. They think a museum should be bright. Last month a boy of six asked the best question of the year. "Is the silk sleeping?" I said yes. He was so happy with the answer that he told every visitor at the door. Now I use his words too. The silk is sleeping, and we are keeping the room quiet for it. It is not a scientific answer. But it makes people walk more softly.', '文物修复与历史(目的·结果状语从句)', 128, 1, '[{"q": "Why is the silk room dark?", "type": "choice", "answer": "C", "options": ["Because the lights are broken.", "Because visitors like a quiet room.", "So that the colours of the silk can last.", "Because the museum saves money."], "explanation": "''We keep the room dark so that the colours can last.''"}, {"q": "What did the six-year-old boy ask?", "type": "choice", "answer": "A", "options": ["Whether the silk was sleeping.", "Why the room was so small.", "How old the silk was.", "Where the lights were."], "explanation": "''Last month a boy of six asked the best question of the year. \"Is the silk sleeping?\"''"}, {"q": "Why does the writer still use the boy''s words?", "type": "choice", "answer": "D", "options": ["Because the boy comes every Saturday.", "Because the museum told him to.", "Because it is a scientific answer.", "Because it makes visitors move more quietly."], "explanation": "''It is not a scientific answer. But it makes people walk more softly.''"}]'::jsonb, '[{"word": "silk", "cn": "丝绸"}, {"word": "visitor", "cn": "参观者(visit + -or)"}, {"word": "scientific", "cn": "科学的"}]'::jsonb);
-- U4 精读《Four words in a notebook》179 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U4', 'Four words in a notebook', 'For years my great-grandfather was only a name on the back of a photo. He was gone many years before my birth, and nobody at home talked about him much. Last spring my grandmother opened an old tin box. Inside there were letters, a pair of glasses and a small notebook. "He was a doctor who walked from village to village," she said. "In winter the river froze, and he was the only person who would cross it at night." I asked what he was like. "He was a quiet man whom the children were never afraid of." In the notebook I found lists of names and dates. Beside one name he wrote four words: "She is walking again." My grandmother is the only person who still remembers his voice. The old people who live along that river still know his name. Now I keep the notebook on my desk. I do not know most of the people whom he helped. But when I am tired of a hard question, I read those four words, and I keep going.', '平凡英雄(who/whom 定语从句)', 179, 0, '[{"q": "Why did the writer know little about his great-grandfather?", "type": "choice", "answer": "B", "options": ["Because the family lost all his letters.", "Because he was gone many years before the writer was born and nobody talked about him.", "Because he lived in another country.", "Because his photo was thrown away."], "explanation": "''He was gone many years before my birth, and nobody at home talked about him much.''"}, {"q": "What did the grandmother find in the old tin box?", "type": "choice", "answer": "D", "options": ["A pair of shoes and a map.", "A photo and a river stone.", "Some money and a school report.", "Letters, a pair of glasses and a small notebook."], "explanation": "''Inside there were letters, a pair of glasses and a small notebook.''"}, {"q": "What kind of person was the great-grandfather?", "type": "choice", "answer": "A", "options": ["A quiet doctor who helped people in far villages.", "A soldier who fought in many places.", "A teacher who wrote long letters.", "A worker who built a bridge over the river."], "explanation": "''He was a doctor who walked from village to village'' 与 ''He was a quiet man whom the children were never afraid of.''"}, {"q": "What do the four words \"She is walking again\" tell us?", "type": "choice", "answer": "C", "options": ["The great-grandfather liked walking at night.", "A patient left the village on foot.", "Someone he treated got better.", "The notebook was written by a child."], "explanation": "四个词写在一个病人名字旁边,说明这位病人在他医治后重新站了起来。"}, {"q": "Why does the writer keep the notebook on his desk?", "type": "choice", "answer": "B", "options": ["Because it is worth a lot of money.", "Because those four words give him courage when work is hard.", "Because his grandmother asked him to keep it.", "Because he wants to write in it himself."], "explanation": "''when I am tired of a hard question, I read those four words, and I keep going.''"}]'::jsonb, '[{"word": "great-grandfather", "cn": "曾祖父"}, {"word": "tin box", "cn": "铁盒"}, {"word": "froze", "cn": "结冰(freeze 的过去式)"}, {"word": "cross", "cn": "横渡,穿过"}]'::jsonb);
-- U4 泛读《The man at the crossing》135 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U4', 'The man at the crossing', 'Every morning at seven, a man in a yellow coat stands at the crossing near our school gate. His name is Uncle Fang. He is not a policeman. He is a retired worker who lives in the next street. He started six winters ago, after a small accident happened at the same corner. Nobody asked him to do it. He knows the children who cross there every day. He knows who walks fast and who dreams while walking. "Slow down, little runner," he says. On rainy days he brings a big umbrella. The parents who wait on the other side often bring him hot water. Last term our class wrote him a card. He read it twice, then put it in his coat pocket. He is a gentle man whom nobody in our school forgets.', '平凡英雄(who/whom 定语从句)', 135, 1, '[{"q": "Who is Uncle Fang?", "type": "choice", "answer": "C", "options": ["A policeman at the school gate.", "A teacher from our school.", "A retired worker who lives in the next street.", "A parent who waits for his child."], "explanation": "''He is not a policeman. He is a retired worker who lives in the next street.''"}, {"q": "Why did Uncle Fang start his work?", "type": "choice", "answer": "A", "options": ["Because a small accident happened at the corner.", "Because the school paid him.", "Because the police asked him to help.", "Because he wanted to meet the parents."], "explanation": "''He started six winters ago, after a small accident happened at the same corner. Nobody asked him to do it.''"}, {"q": "How do people show their thanks to him?", "type": "choice", "answer": "D", "options": ["They give him a yellow coat.", "They walk him home after school.", "They ask the school to pay him.", "They bring him hot water and write him cards."], "explanation": "''The parents who wait on the other side often bring him hot water.'' 与 ''Last term our class wrote him a card.''"}]'::jsonb, '[{"word": "crossing", "cn": "人行横道"}, {"word": "retired", "cn": "退休的"}, {"word": "umbrella", "cn": "雨伞"}]'::jsonb);
-- U4 泛读《The last bus》132 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U4', 'The last bus', 'The last bus of the night leaves the station at half past eleven. Driver Song has taken this line for nine years. Most of the people who get on after eleven are tired. Some workers fall asleep before the third stop. Driver Song drives slowly at that hour. When he comes to a sleeping passenger''s stop, he says the name of the street twice, in a low voice. One winter night a young woman missed her stop because she was crying. He did not ask why. He drove to the end of the line, then took her back for free. "Everyone has a bad night," he once told a neighbour. He is a quiet man whom his passengers seldom thank. But the workers who ride the last bus all know his voice.', '平凡英雄(who/whom 定语从句)', 132, 1, '[{"q": "What is special about the way Driver Song drives at night?", "type": "choice", "answer": "B", "options": ["He drives faster to save time.", "He drives slowly and calls out the stops in a low voice.", "He stops the bus at every corner.", "He asks the passengers to stay awake."], "explanation": "''Driver Song drives slowly at that hour. When he comes to a sleeping passenger''s stop, he says the name of the street twice, in a low voice.''"}, {"q": "What did he do for the young woman?", "type": "choice", "answer": "D", "options": ["He asked her why she was crying.", "He called her family.", "He gave her some money.", "He took her back to her stop for free."], "explanation": "''He drove to the end of the line, then took her back for free.''"}, {"q": "What does the last sentence tell us?", "type": "choice", "answer": "A", "options": ["The night workers know him well even if they seldom say thanks.", "The passengers often write to the bus company.", "He wants to change to a daytime line.", "His voice is too low for passengers to hear."], "explanation": "''He is a quiet man whom his passengers seldom thank. But the workers who ride the last bus all know his voice.''"}]'::jsonb, '[{"word": "passenger", "cn": "乘客"}, {"word": "line", "cn": "线路,路线"}, {"word": "for free", "cn": "免费"}]'::jsonb);
-- U4 泛读《She knows every name》116 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U4', 'She knows every name', 'Aunt Mei cleans the third floor of our teaching building. She starts at six and finishes at four. She is the only person in the building who knows every student by name. Nobody taught her. She just listens. When a boy loses his key, he goes to her first. When a girl feels ill in the afternoon, she sits in the small room beside the stairs, and Aunt Mei brings her warm water. Last year countless leaves fell into the corridor after a storm. Six students who live near the school came back on Sunday to help her. They finished before lunch. "You did not have to come," she said. "Neither did you," one boy answered.', '平凡英雄(who/whom 定语从句)', 116, 1, '[{"q": "What is special about Aunt Mei?", "type": "choice", "answer": "C", "options": ["She starts work later than the teachers.", "She teaches students in the small room.", "She knows every student in the building by name.", "She lives near the school gate."], "explanation": "''She is the only person in the building who knows every student by name.''"}, {"q": "What happens when a student feels ill in the afternoon?", "type": "choice", "answer": "A", "options": ["Aunt Mei brings her warm water.", "Aunt Mei calls her parents.", "Aunt Mei takes her home.", "Aunt Mei asks a teacher for help."], "explanation": "''When a girl feels ill in the afternoon, she sits in the small room beside the stairs, and Aunt Mei brings her warm water.''"}, {"q": "What does the boy''s answer mean?", "type": "choice", "answer": "B", "options": ["He was sorry that he came so late.", "Aunt Mei helps them without having to, so they help her the same way.", "He wanted Aunt Mei to thank them.", "He thought the work was too hard."], "explanation": "''\"You did not have to come,\" she said. \"Neither did you,\" one boy answered.'' 意为她平日的帮助同样不是分内之事。"}]'::jsonb, '[{"word": "corridor", "cn": "走廊"}, {"word": "storm", "cn": "暴风雨"}]'::jsonb);
-- U4 泛读《The river team》128 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U4', 'The river team', 'In our town there is a small team of about twenty people. They are not soldiers. They are shop owners, drivers and teachers who go to the river when someone is in danger. The leader is a woman who runs a noodle shop near the bridge. Her phone never turns off. In summer the water rises quickly. The team members who live close to the bridge get there first. They carry ropes, not cameras. Two years ago they helped a survivor of a boat accident. He came back last spring with his family and ate at the noodle shop. He did not say much. He just washed the bowls before he left. The leader kept his photo behind the door. "He is one of us now," she says.', '平凡英雄(who/whom 定语从句)', 128, 1, '[{"q": "Who are the members of the river team?", "type": "choice", "answer": "D", "options": ["Soldiers from a nearby town.", "Students from the local school.", "Doctors and nurses.", "Shop owners, drivers and teachers."], "explanation": "''They are shop owners, drivers and teachers who go to the river when someone is in danger.''"}, {"q": "Why do the members who live close to the bridge get there first?", "type": "choice", "answer": "B", "options": ["Because they have the best boats.", "Because they live nearest to the river.", "Because they are the youngest.", "Because the leader calls them first."], "explanation": "''The team members who live close to the bridge get there first.''"}, {"q": "What did the survivor do when he came back?", "type": "choice", "answer": "A", "options": ["He washed the bowls in the noodle shop.", "He gave the team new ropes.", "He joined the team at once.", "He took a photo with the leader."], "explanation": "''He did not say much. He just washed the bowls before he left.''"}]'::jsonb, '[{"word": "survivor", "cn": "生还者,幸存者(survive + -or)"}, {"word": "rope", "cn": "绳子"}, {"word": "noodle", "cn": "面条"}]'::jsonb);
-- U5 精读《The park that closed for a year》170 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U5', 'The park that closed for a year', 'The small park near our flat closed for one whole year. Workers were mending the old wall, and the gate stayed locked. Last month it opened again. My father and I went in on the first morning. The pond which was green and dirty before is clear now. The small fish that we saw last week are back near the stones. The grass that grows along the path is taller than my knee. The bird book we bought last spring is suddenly useful. In one hour we found four kinds of birds. My father says two of them never came here before. Nobody planted the flowers that stand near the north gate. The wind brought the seeds. Our city did not do anything special. It only stopped for a year. Now the gate is open again. People walk in, and the birds move a little farther away. That is fair. But my father keeps the bird book in his bag, and we go early, when the park is still quiet.', '人与自然的平衡(that/which 定语从句·引导词省略)', 170, 0, '[{"q": "Why was the park closed for a year?", "type": "choice", "answer": "C", "options": ["Because too many birds lived there.", "Because the pond was too dirty to clean.", "Because workers were mending the old wall.", "Because the city had no money for it."], "explanation": "''Workers were mending the old wall, and the gate stayed locked.''"}, {"q": "What changed in the pond during that year?", "type": "choice", "answer": "A", "options": ["It became clear, and small fish appeared.", "It dried up completely.", "It was filled with stones.", "It turned green and dirty."], "explanation": "''The pond which was green and dirty before is clear now. The small fish that we saw last week are back near the stones.''"}, {"q": "Why is the bird book suddenly useful?", "type": "choice", "answer": "D", "options": ["Because the writer is studying birds at school.", "Because his father wrote part of it.", "Because the park sells the same book now.", "Because there are many more birds in the park."], "explanation": "''The bird book we bought last spring is suddenly useful. In one hour we found four kinds of birds.''"}, {"q": "What does \"Our city did not do anything special. It only stopped for a year\" mean?", "type": "choice", "answer": "B", "options": ["The city forgot to look after the park.", "Nature came back mainly because people stayed away.", "The workers did a very good job on the pond.", "The city planted the flowers near the north gate."], "explanation": "''Nobody planted the flowers that stand near the north gate. The wind brought the seeds.'' 说明恢复靠的是人退出,不是人的作为。"}, {"q": "Why do the writer and his father go to the park early?", "type": "choice", "answer": "A", "options": ["Because the park is quiet then and the birds stay close.", "Because the gate closes at noon.", "Because they want to meet the workers.", "Because the grass is shorter in the morning."], "explanation": "''People walk in, and the birds move a little farther away.'' 与 ''we go early, when the park is still quiet.''"}]'::jsonb, '[{"word": "mend", "cn": "修补,修理"}, {"word": "pond", "cn": "池塘"}, {"word": "knee", "cn": "膝盖"}, {"word": "seed", "cn": "种子"}]'::jsonb);
-- U5 泛读《The bag on the door》126 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U5', 'The bag on the door', 'My mother hangs a cloth bag on the back of our front door. It is grey and a little old. The rule in our home is simple: nobody leaves without it. We started three years ago. At first I often forgot, and the plastic bags that I brought home filled a whole drawer. My father counted them one Sunday. Forty-one. Now the drawer is empty. The cloth bag we use every week is still the same one. It has carried rice, books, a football and once a small cat. Some friends say one family cannot change anything. Maybe they are right. But the bag costs nothing, and it takes no time. A habit which is easy to keep is worth more than a plan nobody follows.', '人与自然的平衡(that/which 定语从句·引导词省略)', 126, 1, '[{"q": "What is the rule in the writer''s home?", "type": "choice", "answer": "B", "options": ["Everyone must clean the drawer on Sunday.", "Nobody leaves home without the cloth bag.", "Plastic bags must be kept in a drawer.", "Everyone must carry books in the bag."], "explanation": "''The rule in our home is simple: nobody leaves without it.''"}, {"q": "What did the father do one Sunday?", "type": "choice", "answer": "D", "options": ["He bought a new cloth bag.", "He threw the drawer away.", "He carried rice in the bag.", "He counted the plastic bags at home."], "explanation": "''My father counted them one Sunday. Forty-one.''"}, {"q": "What does the last sentence mean?", "type": "choice", "answer": "A", "options": ["A small habit people can keep is better than a big plan they cannot.", "Cloth bags are cheaper than plastic ones.", "One family can change the whole world.", "Plans are more important than habits."], "explanation": "''A habit which is easy to keep is worth more than a plan nobody follows.''"}]'::jsonb, '[{"word": "drawer", "cn": "抽屉"}, {"word": "habit", "cn": "习惯"}, {"word": "plastic", "cn": "塑料(制)的"}]'::jsonb);
-- U5 泛读《The lights we turned down》132 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U5', 'The lights we turned down', 'Every autumn, small birds fly over our city at night. Our science teacher told us that bright lights make them lose their way. Some of them are endangered. Last October our class wrote a short letter to the office of our school. We asked for one thing: turn off the tall lights on the sports field after ten o''clock. The answer we got was short. "We will try it for a month." In November a teacher who studies birds walked around the field each morning. He found fewer birds on the ground than in other years. The school kept the new rule. It is a small field in a big city. But the sky above it is a little darker now, and the birds that pass over us are a little safer.', '人与自然的平衡(that/which 定语从句·引导词省略)', 132, 1, '[{"q": "Why are bright lights a problem for the birds?", "type": "choice", "answer": "C", "options": ["They make the birds fly faster.", "They make the field too hot.", "They make the birds lose their way.", "They stop the birds from eating."], "explanation": "''Our science teacher told us that bright lights make them lose their way.''"}, {"q": "What did the class ask the school to do?", "type": "choice", "answer": "A", "options": ["To turn off the tall lights after ten o''clock.", "To build a new sports field.", "To invite a bird teacher to school.", "To write a letter to the city."], "explanation": "''We asked for one thing: turn off the tall lights on the sports field after ten o''clock.''"}, {"q": "Why did the school keep the new rule?", "type": "choice", "answer": "D", "options": ["Because the students asked again.", "Because the lights were broken.", "Because the rule saved a lot of money.", "Because fewer birds were found on the ground."], "explanation": "''He found fewer birds on the ground than in other years. The school kept the new rule.''"}]'::jsonb, '[{"word": "endangered", "cn": "濒危的,濒临灭绝的"}, {"word": "lose one''s way", "cn": "迷路"}, {"word": "field", "cn": "场地(此处指运动场)"}]'::jsonb);
-- U5 泛读《The roof that makes power》123 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U5', 'The roof that makes power', 'Two summers ago our school put solar panels on the roof of the library. Most of us did not care. A roof is a roof. Then the physics teacher put a small screen in the hall. It shows the power the panels make each day. On sunny days the number climbs quickly. On grey days it hardly moves. Now students stop in front of it. Someone always says, "Look, it is a good day today." The screen which nobody asked for has changed something. We know how much light our library uses. We know what a cloudy week costs. The panels do not make the school rich. But the number on that screen makes the sun feel like a thing we can count.', '人与自然的平衡(that/which 定语从句·引导词省略)', 123, 1, '[{"q": "What did the school put on the library roof?", "type": "choice", "answer": "B", "options": ["A small screen.", "Solar panels.", "A new hall.", "A weather station."], "explanation": "''Two summers ago our school put solar panels on the roof of the library.''"}, {"q": "What does the screen in the hall show?", "type": "choice", "answer": "A", "options": ["How much power the panels make each day.", "How many students use the library.", "The weather for the coming week.", "The cost of the panels."], "explanation": "''It shows the power the panels make each day.''"}, {"q": "How did the screen change the students?", "type": "choice", "answer": "C", "options": ["They now study in the hall.", "They stopped using the library lights.", "They started to notice the sun and the school''s power use.", "They asked for more panels."], "explanation": "''Now students stop in front of it.'' 与 ''We know how much light our library uses.''"}]'::jsonb, '[{"word": "solar panel", "cn": "太阳能电池板"}, {"word": "physics", "cn": "物理(学)"}, {"word": "screen", "cn": "屏幕"}]'::jsonb);
-- U5 泛读《One river, two lists》122 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U5', 'One river, two lists', 'On the first Saturday of every month, about thirty people walk along our river with bags. They pick up the rubbish they find on the bank. The team keeps two lists. The first one is short: the things that go to the recycling centre. The second is long: the things that cannot be used again. Old Aunt Guo has kept the lists for six years. She says the second list is getting shorter. Nobody knows exactly why. Perhaps the shops nearby changed. Perhaps people saw the bags and felt something. Last month a boy of nine joined for the first time. He asked which list was more important. Aunt Guo thought for a moment. "The one we hope to close," she said.', '人与自然的平衡(that/which 定语从句·引导词省略)', 122, 1, '[{"q": "What do the people do on the first Saturday of every month?", "type": "choice", "answer": "D", "options": ["They swim in the river.", "They plant trees on the bank.", "They sell things by the river.", "They pick up rubbish along the river."], "explanation": "''about thirty people walk along our river with bags. They pick up the rubbish they find on the bank.''"}, {"q": "What is on the second list?", "type": "choice", "answer": "A", "options": ["Things that cannot be used again.", "Things that go to the recycling centre.", "The names of the team members.", "The dates of the walks."], "explanation": "''The second is long: the things that cannot be used again.''"}, {"q": "What does Aunt Guo mean by \"The one we hope to close\"?", "type": "choice", "answer": "B", "options": ["The recycling centre should be closed.", "She hopes the list of useless rubbish will one day be empty.", "The team should stop keeping lists.", "The first list is too short to keep."], "explanation": "''She says the second list is getting shorter.'' 与该问答呼应,指希望「不可再用」那一类最终归零。"}]'::jsonb, '[{"word": "recycling centre", "cn": "回收站"}, {"word": "bag", "cn": "袋子(此处指捡垃圾用的收集袋)"}, {"word": "nearby", "cn": "附近的"}]'::jsonb);
-- U6 精读《The fourth word》168 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U6', 'The fourth word', 'Look around your classroom. The pen in your hand, the cover of your notebook, the frame of the window — many of them are made of the same material. Three words explain why plastic spread so quickly: light, cheap and long-lasting. A plastic box is useful in a kitchen and harmless in a school bag. The trouble is the fourth word: it stays. A paper bag breaks down in a season. A plastic one may stay in the ground far longer than the person who dropped it. So is plastic good or bad? The question is not helpful. A material is neither. The answer lies in what we choose to do with it. We can reuse the bottle we bought this morning. We can upcycle an old box into a pen holder. We can carry a cloth bag and waste less. Plastic waste is a problem people made, and problems people made can be made smaller. Using it wisely, or unwisely, is the part that belongs to us.', '绿色生活(构词法)', 168, 0, '[{"q": "Why did plastic spread so quickly?", "type": "choice", "answer": "C", "options": ["Because it is easy to break down.", "Because it is made from wood.", "Because it is light, cheap and long-lasting.", "Because it was first used in classrooms."], "explanation": "''Three words explain why plastic spread so quickly: light, cheap and long-lasting.''"}, {"q": "What is \"the fourth word\" in the title?", "type": "choice", "answer": "A", "options": ["That plastic stays for a very long time.", "That plastic is cheap to make.", "That plastic is useful in a kitchen.", "That plastic can be carried in a bag."], "explanation": "''The trouble is the fourth word: it stays.''"}, {"q": "How does the writer answer the question \"good or bad\"?", "type": "choice", "answer": "D", "options": ["Plastic is mostly good.", "Plastic is mostly bad.", "Only paper bags are good.", "A material is neither; our choices decide."], "explanation": "''A material is neither. The answer lies in what we choose to do with it.''"}, {"q": "Which of these does the writer suggest doing?", "type": "choice", "answer": "B", "options": ["Burning old plastic boxes.", "Turning an old box into a pen holder.", "Buying a new bottle every morning.", "Hiding plastic waste in the ground."], "explanation": "''We can upcycle an old box into a pen holder.''"}, {"q": "What does \"unwisely\" mean in the last sentence?", "type": "choice", "answer": "C", "options": ["in a cheap way", "in a quick way", "in a foolish way", "in a quiet way"], "explanation": "前缀 un- 表否定,加在 wisely 前构成反义,故意为「不明智地」。"}]'::jsonb, '[{"word": "long-lasting", "cn": "耐用的,持久的(long + lasting 合成)"}, {"word": "harmless", "cn": "无害的(harm + -less)"}, {"word": "upcycle", "cn": "升级改造(up- + cycle)"}, {"word": "wisely", "cn": "明智地(wise + -ly)"}]'::jsonb);
-- U6 泛读《The bottle wall》139 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U6', 'The bottle wall', 'Behind our science building there is a small greenhouse. One of its walls is made of bottles. Two winters ago the old wall broke. The school had no money for a new one, so the science club asked a question: could we build it from something people throw away? For three months students brought clear bottles from home. The club washed every one of them. The wall they built is not beautiful, but it works. Sunlight passes through the glass, and the plants inside stay warm even when the wind is cold. Visitors are often surprised when they hear the story, and the wall itself is surprising: nobody expects a wall to let in light. "We did not upcycle the bottles to save money," our teacher says. "We did it so that everyone could see what waste can become."', '绿色生活(构词法)', 139, 1, '[{"q": "Why did the science club build a wall from bottles?", "type": "choice", "answer": "C", "options": ["Because bottles are stronger than bricks.", "Because the school wanted a beautiful wall.", "Because the old wall broke and there was no money for a new one.", "Because the plants needed more water."], "explanation": "''Two winters ago the old wall broke. The school had no money for a new one, so the science club asked a question…''"}, {"q": "What is good about the bottle wall?", "type": "choice", "answer": "A", "options": ["Sunlight passes through it and keeps the plants warm.", "It is the most beautiful wall in the school.", "It cost more than a normal wall.", "It keeps all the light out."], "explanation": "''Sunlight passes through the glass, and the plants inside stay warm even when the wind is cold.''"}, {"q": "Why did the teacher say they built it?", "type": "choice", "answer": "D", "options": ["To win a school prize.", "To use up the old bottles quickly.", "To save money for the science club.", "So that everyone could see what waste can become."], "explanation": "''We did it so that everyone could see what waste can become.''"}]'::jsonb, '[{"word": "greenhouse", "cn": "温室(green + house 合成)"}, {"word": "upcycle", "cn": "升级改造"}, {"word": "surprising", "cn": "令人惊奇的(修饰事物)"}, {"word": "surprised", "cn": "感到惊奇的(修饰人)"}]'::jsonb);
-- U6 泛读《Two buses》131 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U6', 'Two buses', 'Our school has two buses. Before last autumn, only one of them ran. Most families drove their children to the gate, and the road outside was full of cars every morning. A teacher who lives near the school counted the cars for one week. Then she showed the number to the parents at a meeting. Nobody argued. The school opened the second bus line the next month. Now the road is quieter, and the air near the gate is cleaner. Parents who once waited in their cars for twenty minutes get half an hour back each day. The buses do not solve everything. They still burn fuel, and their emissions do not disappear. But one bus takes the place of about thirty cars. Small numbers, our teacher says, are still numbers.', '绿色生活(构词法)', 131, 1, '[{"q": "What was the problem before last autumn?", "type": "choice", "answer": "B", "options": ["The school had no bus at all.", "Too many families drove to the school gate.", "The road outside was closed.", "The bus was always late."], "explanation": "''Most families drove their children to the gate, and the road outside was full of cars every morning.''"}, {"q": "What did the teacher do to change things?", "type": "choice", "answer": "A", "options": ["She counted the cars and showed the number to the parents.", "She asked the city to close the road.", "She bought a new bus herself.", "She wrote a letter to the newspaper."], "explanation": "''A teacher who lives near the school counted the cars for one week. Then she showed the number to the parents at a meeting.''"}, {"q": "What does the writer admit about the buses?", "type": "choice", "answer": "D", "options": ["They are slower than cars.", "They cost the school too much.", "Parents do not like them.", "They still burn fuel and produce emissions."], "explanation": "''They still burn fuel, and their emissions do not disappear.''"}]'::jsonb, '[{"word": "emission", "cn": "排放物,散发物"}, {"word": "fuel", "cn": "燃料"}, {"word": "argue", "cn": "争辩"}]'::jsonb);
-- U6 泛读《The repair table》138 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U6', 'The repair table', 'On the last Friday of each month, a long table stands in our school hall. People bring things that do not work: a lamp, a school bag with a broken zip, a toy car. Three teachers and six students sit behind the table. They do not sell anything. They mend what people bring. The rule is simple: the owner stays and watches. If you do not watch, they will not mend it. "We are not a shop," the maths teacher says. "We are a class." Last month a boy brought a chair which his grandfather made. One leg was loose. The boy left with the chair and with a new skill. Nothing on that table is valuable. But the pile of broken things gets smaller every month, and the pile of people who can mend them gets larger.', '绿色生活(构词法)', 138, 1, '[{"q": "What happens at the long table?", "type": "choice", "answer": "C", "options": ["People sell old things.", "Students give away school bags.", "Broken things are mended.", "Teachers teach maths lessons."], "explanation": "''People bring things that do not work… They mend what people bring.''"}, {"q": "Why must the owner stay and watch?", "type": "choice", "answer": "B", "options": ["Because the table is often busy.", "Because the owner is meant to learn the skill.", "Because the teachers need help.", "Because things get lost easily."], "explanation": "''\"We are not a shop,\" the maths teacher says. \"We are a class.\"'' 与 ''The boy left with the chair and with a new skill.''"}, {"q": "What does the last sentence mean?", "type": "choice", "answer": "A", "options": ["More and more people are learning to mend things.", "The table is getting longer each month.", "Fewer people come to the hall now.", "The school is buying fewer new things."], "explanation": "''the pile of broken things gets smaller every month, and the pile of people who can mend them gets larger.''"}]'::jsonb, '[{"word": "mend", "cn": "修理"}, {"word": "zip", "cn": "拉链"}, {"word": "loose", "cn": "松的,不牢固的"}, {"word": "pile", "cn": "堆"}]'::jsonb);
-- U6 泛读《What the bin told us》122 词
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (9, 'junior_fltrp', 'wy9A', 'U6', 'What the bin told us', 'Our class did a strange piece of homework in May. For one week we did not throw anything away. Everything went into a big box under the back window. On Friday we opened it. The result was surprising, and we were surprised. Half of the box was paper — old worksheets, printed on one side only. Nobody in the class planned to waste it. It simply happened, page by page. The next week we started a paper tray beside the printer. Any sheet with a clean back goes there. The tray is not an environmental plan. It is a shelf. But since May our class has printed far fewer new pages, and the box under the window has never been full again.', '绿色生活(构词法)', 122, 1, '[{"q": "What was the homework in May?", "type": "choice", "answer": "D", "options": ["To count the paper in the printer.", "To clean the classroom every day.", "To write about the environment.", "To keep everything they would normally throw away."], "explanation": "''For one week we did not throw anything away. Everything went into a big box under the back window.''"}, {"q": "What did the class find in the box?", "type": "choice", "answer": "A", "options": ["Half of it was paper printed on one side only.", "Most of it was plastic bottles.", "It was almost empty.", "It was full of old books."], "explanation": "''Half of the box was paper — old worksheets, printed on one side only.''"}, {"q": "What has changed since May?", "type": "choice", "answer": "B", "options": ["The class stopped using the printer.", "The class prints far fewer new pages.", "The box was moved to another room.", "The school bought a new printer."], "explanation": "''since May our class has printed far fewer new pages, and the box under the window has never been full again.''"}]'::jsonb, '[{"word": "worksheet", "cn": "练习纸"}, {"word": "tray", "cn": "托盘,盘子"}, {"word": "environmental", "cn": "自然环境的(environment + -al)"}]'::jsonb);

DO $$
DECLARE tot int; intn int; extn int; qbad int; peru int; wcbad int;
BEGIN
  SELECT count(*) INTO tot FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A';
  IF tot <> 30 THEN RAISE EXCEPTION 'total=% 期望 30', tot; END IF;

  SELECT count(*) INTO intn FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A' AND difficulty=0;
  IF intn <> 6 THEN RAISE EXCEPTION '精读(diff0)=% 期望 6', intn; END IF;

  SELECT count(*) INTO extn FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A' AND difficulty=1;
  IF extn <> 24 THEN RAISE EXCEPTION '泛读(diff1)=% 期望 24', extn; END IF;

  -- 题数:精读必须 5 题、泛读必须 3 题
  SELECT count(*) INTO qbad FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND jsonb_array_length(questions) <> (CASE WHEN difficulty=0 THEN 5 ELSE 3 END);
  IF qbad <> 0 THEN RAISE EXCEPTION '题数不符(精读5/泛读3)的篇=%', qbad; END IF;

  -- 每单元必须恰好 5 篇(1 精读 + 4 泛读)
  SELECT count(*) INTO peru FROM (
    SELECT unit FROM public.junior_reading
     WHERE publisher='junior_fltrp' AND volume='wy9A'
     GROUP BY unit
    HAVING count(*) <> 5
        OR count(*) FILTER (WHERE difficulty=0) <> 1
        OR count(*) FILTER (WHERE difficulty=1) <> 4) t;
  IF peru <> 0 THEN RAISE EXCEPTION '每单元≠5篇(1精读+4泛读)的单元数=%', peru; END IF;

  -- word_count 必须与 body 的实际词数一致(防生成期与落库期不同步)
  SELECT count(*) INTO wcbad FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND word_count <> array_length(regexp_split_to_array(btrim(body), '\s+'), 1);
  IF wcbad <> 0 THEN RAISE EXCEPTION 'word_count 与正文词数不符的篇=%', wcbad; END IF;

  -- vocab_notes:不得为 NULL、不得空数组、每篇至少 2 条
  SELECT count(*) INTO wcbad FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume='wy9A'
     AND (vocab_notes IS NULL OR jsonb_array_length(vocab_notes) < 2);
  IF wcbad <> 0 THEN RAISE EXCEPTION 'vocab_notes 为空或少于 2 条的篇=%', wcbad; END IF;

  -- 不得污染其它册
  SELECT count(*) INTO tot FROM public.junior_reading
   WHERE publisher='junior_fltrp' AND volume<>'wy9A' AND unit IS NULL;
  IF tot <> 0 THEN RAISE EXCEPTION '发现 % 行外研社阅读缺 unit,疑似误伤', tot; END IF;
END $$;

COMMIT;

-- ============================================================
-- 跑完必看:期望 6 行;total 全 5、精读 1、泛读 4、精读题数 5、泛读题数 3
-- ============================================================
SELECT unit,
       count(*) AS total,
       count(*) FILTER (WHERE difficulty=0) AS intensive,
       count(*) FILTER (WHERE difficulty=1) AS extensive,
       min(jsonb_array_length(questions)) FILTER (WHERE difficulty=0) AS q_intensive,
       min(jsonb_array_length(questions)) FILTER (WHERE difficulty=1) AS q_extensive,
       min(word_count) AS wc_min, max(word_count) AS wc_max,
       min(jsonb_array_length(vocab_notes)) AS vocab_min,
       max(jsonb_array_length(vocab_notes)) AS vocab_max
  FROM public.junior_reading
 WHERE publisher='junior_fltrp' AND volume='wy9A'
 GROUP BY unit ORDER BY unit;
